import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { 
  LayoutDashboard, Users, ShoppingBag, CreditCard, BarChart3, MessageSquare, 
  Settings, LogOut, User, Shield, TrendingUp, Bell, FileText, Calendar,
  ShieldCheck, Database, Server
} from 'lucide-react';

const Sidebar = ({ sidebarOpen, onLogout }) => {

  // 🔥 Correction : récupérer la location via React Router
  const location = useLocation();

  const userEmail = localStorage.getItem('userEmail') || 'enzo@gmail.com';

  const navItems = [
    { to: "/dashboard", icon: <LayoutDashboard className="h-5 w-5" />, label: "Tableau de bord", exact: true },
    { to: "/dashboard/users", icon: <Users className="h-5 w-5" />, label: "Utilisateurs", badge: "42", badgeColor: "accent" },
    { to: "/dashboard/products", icon: <ShoppingBag className="h-5 w-5" />, label: "Produits", badge: "156", badgeColor: "secondary" },
    { to: "/dashboard/orders", icon: <CreditCard className="h-5 w-5" />, label: "Commandes", badge: "24", badgeColor: "primary" },
    { to: "/dashboard/analytics", icon: <BarChart3 className="h-5 w-5" />, label: "Analytique" },
    { to: "/dashboard/messages", icon: <MessageSquare className="h-5 w-5" />, label: "Messages", badge: "3", badgeColor: "accent" },
    { to: "/dashboard/settings", icon: <Settings className="h-5 w-5" />, label: "Paramètres" },
  ];

  const quickStats = [
    { label: "Utilisateurs actifs", value: "1,234" },
    { label: "Taux de conversion", value: "3.42%", valueColor: "text-accent-500" },
    { label: "Commande moyenne", value: "$245", valueColor: "text-primary-500" },
    { label: "Satisfaction", value: "4.8/5", valueColor: "text-green-500" },
  ];

  const secondaryNav = [
    { to: "/dashboard/reports", icon: <FileText className="h-4 w-4" />, label: "Rapports" },
    { to: "/dashboard/calendar", icon: <Calendar className="h-4 w-4" />, label: "Calendrier" },
    { to: "/dashboard/notifications", icon: <Bell className="h-4 w-4" />, label: "Notifications" },
  ];

  const systemNav = [
    { to: "/dashboard/system", icon: <Server className="h-4 w-4" />, label: "Système" },
    { to: "/dashboard/database", icon: <Database className="h-4 w-4" />, label: "Base de données" },
    { to: "/dashboard/backup", icon: <ShieldCheck className="h-4 w-4" />, label: "Sauvegarde" },
  ];

  return (
    <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl border-r border-neutral-200/50 dark:border-neutral-800/50 transform transition-transform duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0`}>
      <div className="flex flex-col h-full">

        {/* Logo */}
        <div className="p-6 border-b border-neutral-200/50 dark:border-neutral-800/50">
          <div className="flex items-center space-x-3">
            <div className="h-10 w-10 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
              <Shield className="h-6 w-6 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-neutral-900 dark:text-white">Admin<span className="text-primary-600 dark:text-primary-400">Pro</span></h1>
              <p className="text-xs text-neutral-500 dark:text-neutral-400">Dashboard Premium</p>
            </div>
          </div>
        </div>

        {/* User */}
        <div className="p-6 border-b border-neutral-200/50 dark:border-neutral-800/50">
          <div className="flex items-center space-x-3">
            <div className="h-12 w-12 rounded-xl bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center">
              <User className="h-6 w-6 text-white" />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-neutral-900 dark:text-white truncate">Enzo Admin</p>
              <p className="text-xs text-neutral-500 dark:text-neutral-400 truncate">{userEmail}</p>
              <div className="flex items-center mt-1">
                <div className="h-2 w-2 rounded-full bg-green-500 mr-2"></div>
                <span className="text-xs text-green-600 dark:text-green-400">En ligne</span>
              </div>
            </div>
          </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 p-4 overflow-y-auto">

          {/* NAVIGATION PRINCIPALE */}
          <div className="mb-6">
            <h3 className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-3 px-3">
              Navigation
            </h3>

            <ul className="space-y-1">
              {navItems.map((item) => {

                const isActive = item.exact
                  ? location.pathname === item.to
                  : location.pathname.startsWith(item.to);

                return (
                  <li key={item.to}>
                    <Link
                      to={item.to}
                      className={`flex items-center space-x-3 px-4 py-3 rounded-xl ${
                        isActive
                          ? "bg-gradient-to-r from-primary-500 to-primary-600 text-white font-medium"
                          : "text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors"
                      }`}
                    >
                      {item.icon}
                      <span>{item.label}</span>

                      {item.badge && (
                        <span className={`ml-auto px-2 py-1 text-xs font-medium rounded-full bg-${item.badgeColor}-500 text-white`}>
                          {item.badge}
                        </span>
                      )}
                    </Link>
                  </li>
                );
              })}
            </ul>
          </div>

